import type { WritingSample } from '@/data/writing-samples';

type ParagraphSeed = { en: string; vi: string; focusVi: string };
type DiscussionSeed = {
  id: string;
  topicSlug: string;
  topicEn: string;
  topicVi: string;
  title: string;
  promptText: string;
  paragraphs: [ParagraphSeed, ParagraphSeed, ParagraphSeed, ParagraphSeed];
  vocabulary: WritingSample['vocabulary'];
};

const SECTIONS = ['introduction', 'body1', 'body2', 'conclusion'] as const;

function makeDiscussion(seed: DiscussionSeed): WritingSample {
  return {
    ...seed,
    task: 'ielts_task2',
    essayKind: 'discussion',
    promptId: `w-${seed.id}`,
    // Nhãn mục tiêu phục vụ học tập, chưa được thẩm định như điểm thi.
    band: 8.0,
    paragraphs: seed.paragraphs.map((part, index) => ({
      id: `${seed.id}-p${index + 1}`,
      section: SECTIONS[index]!,
      ...part,
    })),
  };
}

const SEEDS: DiscussionSeed[] = [
  {
    id: 'sample-t2-extra-discussion2-education', topicSlug: 'education', topicEn: 'Education', topicVi: 'Giáo dục',
    title: 'Final examinations or continuous assessment',
    promptText: 'Some people believe final examinations are the fairest way to assess students, while others prefer coursework and continuous assessment. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Schools need reliable ways to judge what students have learned, yet there is disagreement over whether one final examination or a series of assignments gives the fairest picture. Exams offer a common test under controlled conditions, whereas coursework reflects progress over time. I favour a balanced system that combines both, with neither method determining a student’s result alone.', vi: 'Trường học cần cách đáng tin cậy để đánh giá học sinh đã học gì, nhưng vẫn có bất đồng về việc một kỳ thi cuối hay chuỗi bài tập cho bức tranh công bằng hơn. Thi cử tạo bài kiểm tra chung trong điều kiện được kiểm soát, còn bài tập phản ánh tiến bộ theo thời gian. Tôi ủng hộ hệ thống cân bằng kết hợp cả hai, không để phương pháp nào tự quyết định kết quả của học sinh.', focusVi: 'Mở bài nêu hai cách đánh giá và lập trường kết hợp.' },
      { en: 'Supporters of final examinations value standardisation. Students answer comparable questions at the same time, and external markers can apply a shared scoring guide. This makes it easier to compare achievement across classes and reduces the possibility that a parent or tutor has substantially completed the work. An examination can also reveal whether a learner can recall and apply knowledge independently, an ability that is important in later study and many professions. For these reasons, a common test offers useful evidence of individual performance.', vi: 'Người ủng hộ kỳ thi cuối coi trọng tính chuẩn hoá. Học sinh trả lời câu hỏi tương đương trong cùng thời điểm, còn giám khảo độc lập có thể áp dụng hướng dẫn chấm chung. Điều này giúp so sánh thành tích giữa các lớp dễ hơn và giảm khả năng cha mẹ hay gia sư làm phần lớn bài thay học sinh. Kỳ thi cũng cho thấy người học có thể tự nhớ và vận dụng kiến thức hay không, năng lực quan trọng ở bậc học cao hơn và nhiều nghề nghiệp. Vì những lý do đó, bài kiểm tra chung cung cấp bằng chứng hữu ích về năng lực cá nhân.', focusVi: 'Thân bài 1 giải thích tính chuẩn hoá và khả năng xác nhận năng lực độc lập.' },
      { en: 'However, a single exam can reward short-term memorisation and place excessive weight on performance during a few stressful hours. Coursework allows students to research a question, revise a draft and receive feedback on skills such as planning or collaboration. It can therefore show abilities that a timed test misses. Yet assignments need clear rules and occasional supervised tasks so that the work remains the student’s own. Combining moderated coursework with a shorter examination would capture a wider range of learning without abandoning consistent standards.', vi: 'Tuy nhiên, một kỳ thi duy nhất có thể khuyến khích học thuộc ngắn hạn và đặt trọng số quá lớn vào kết quả trong vài giờ căng thẳng. Bài tập dài hạn cho phép học sinh nghiên cứu câu hỏi, sửa bản nháp và nhận phản hồi về kỹ năng như lập kế hoạch hay hợp tác. Nhờ đó, phương pháp này cho thấy năng lực mà bài thi tính giờ bỏ sót. Dù vậy, bài tập cần quy tắc rõ và một số nhiệm vụ có giám sát để bảo đảm sản phẩm là của học sinh. Kết hợp bài tập được kiểm duyệt với kỳ thi ngắn hơn sẽ đánh giá nhiều mặt học tập mà vẫn giữ tiêu chuẩn nhất quán.', focusVi: 'Thân bài 2 nêu giá trị của bài tập liên tục và điều kiện đảm bảo tính xác thực.' },
      { en: 'Final examinations provide comparability, while coursework shows development and skills that tests cannot easily measure. Neither is fair when used in isolation. A moderated combination gives schools a more complete account of learning and reduces the influence of one unusually good or poor day.', vi: 'Kỳ thi cuối tạo khả năng so sánh, còn bài tập cho thấy sự phát triển và kỹ năng khó đo bằng bài kiểm tra. Không phương pháp nào công bằng nếu được dùng riêng lẻ. Sự kết hợp có kiểm duyệt giúp trường học đánh giá việc học toàn diện hơn và giảm ảnh hưởng của một ngày thi tốt hoặc kém bất thường.', focusVi: 'Kết luận tổng hợp ưu điểm và chốt mô hình đánh giá.' },
    ],
    vocabulary: [
      { phrase: 'under controlled conditions', meaningVi: 'trong điều kiện được kiểm soát', noteVi: 'Cụm chỉ bối cảnh thi thống nhất.' },
      { phrase: 'external markers', meaningVi: 'giám khảo độc lập bên ngoài', noteVi: 'Người chấm không trực tiếp dạy học sinh.' },
      { phrase: 'moderated coursework', meaningVi: 'bài tập được kiểm duyệt/đối chuẩn', noteVi: 'Cách kiểm tra bài tập giữa các lớp hoặc giám khảo.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-environment', topicSlug: 'environment', topicEn: 'Environment', topicVi: 'Môi trường',
    title: 'Nuclear power and renewable energy',
    promptText: 'Some people believe nuclear power is necessary to meet future energy demand, while others think investment should focus entirely on renewable sources. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Countries need reliable electricity while reducing carbon emissions, and this has led to disagreement about the role of nuclear power. Its supporters see it as a steady low-carbon source, whereas critics prefer investment in wind, solar and storage. I believe renewables should lead the transition, but existing nuclear capacity can remain part of a diversified system where safety standards are strong.', vi: 'Các quốc gia cần điện đáng tin cậy trong khi giảm khí thải carbon, dẫn đến bất đồng về vai trò của năng lượng hạt nhân. Người ủng hộ xem đây là nguồn ít carbon ổn định, còn người chỉ trích muốn đầu tư vào gió, mặt trời và lưu trữ. Tôi cho rằng năng lượng tái tạo nên dẫn dắt quá trình chuyển đổi, nhưng công suất hạt nhân hiện có vẫn có thể nằm trong hệ thống đa dạng nếu tiêu chuẩn an toàn nghiêm ngặt.', focusVi: 'Mở bài nêu tranh luận và đưa lập trường ưu tiên tái tạo nhưng không loại bỏ tuyệt đối hạt nhân.' },
      { en: 'Nuclear plants generate electricity regardless of weather, so they can provide a predictable supply when wind or sunlight is weak. Supporters argue that this reliability helps stabilise the grid and reduces dependence on gas, whose price and emissions can fluctuate. A plant also produces large amounts of power from a relatively small site. For countries with suitable expertise and regulation, maintaining such capacity may prevent the energy transition from relying on fossil fuels during periods when renewable output falls.', vi: 'Nhà máy hạt nhân tạo điện bất kể thời tiết, nên có thể cung cấp nguồn ổn định khi gió yếu hoặc thiếu nắng. Người ủng hộ cho rằng độ tin cậy này giúp ổn định lưới và giảm phụ thuộc vào khí đốt, vốn có giá và lượng phát thải biến động. Một nhà máy cũng sản xuất nhiều điện trên diện tích tương đối nhỏ. Với quốc gia có chuyên môn và quy định phù hợp, duy trì công suất này có thể ngăn quá trình chuyển đổi phải dựa vào nhiên liệu hoá thạch khi sản lượng tái tạo giảm.', focusVi: 'Thân bài 1 giải thích lợi thế ổn định nguồn điện và giảm lệ thuộc nhiên liệu hoá thạch.' },
      { en: 'Those favouring renewables point to falling costs and the absence of radioactive waste that must be managed for generations. Solar and wind projects can be built in stages, and distributed systems may give communities more control over supply. However, variable output requires storage, stronger connections between regions or other backup sources. This challenge is serious but increasingly manageable through batteries, demand planning and a mix of technologies. Long-term investment should therefore focus on making renewable systems dependable rather than assuming that one source can meet every need.', vi: 'Người ưu tiên năng lượng tái tạo chỉ ra chi phí giảm và không tạo chất thải phóng xạ cần quản lý qua nhiều thế hệ. Dự án mặt trời và gió có thể xây từng giai đoạn, còn hệ thống phân tán có thể giúp cộng đồng kiểm soát nguồn cung nhiều hơn. Tuy nhiên, sản lượng thay đổi cần lưu trữ, kết nối vùng mạnh hơn hoặc nguồn dự phòng khác. Thách thức này nghiêm trọng nhưng ngày càng có thể xử lý bằng pin, điều phối nhu cầu và kết hợp công nghệ. Vì vậy, đầu tư dài hạn nên tập trung làm hệ thống tái tạo đáng tin cậy thay vì giả định một nguồn có thể đáp ứng mọi nhu cầu.', focusVi: 'Thân bài 2 trình bày lợi ích tái tạo, thừa nhận vấn đề gián đoạn và cách giải quyết.' },
      { en: 'Renewables should receive the largest share of new investment because their costs are declining and their waste burden is lower. Nuclear power can still support reliability in places that can manage its risks responsibly. A diverse low-carbon grid is more resilient than relying exclusively on any single technology.', vi: 'Năng lượng tái tạo nên nhận phần lớn đầu tư mới vì chi phí đang giảm và gánh nặng chất thải thấp hơn. Hạt nhân vẫn có thể hỗ trợ độ ổn định ở nơi quản lý được rủi ro một cách có trách nhiệm. Lưới điện ít carbon đa dạng có khả năng chống chịu tốt hơn hệ thống chỉ phụ thuộc vào một công nghệ.', focusVi: 'Kết luận nêu thứ tự ưu tiên và nguyên tắc đa dạng nguồn cung.' },
    ],
    vocabulary: [
      { phrase: 'diversified system', meaningVi: 'hệ thống đa dạng nguồn', noteVi: 'Cụm chỉ cấu trúc không phụ thuộc vào một nguồn duy nhất.' },
      { phrase: 'radioactive waste', meaningVi: 'chất thải phóng xạ', noteVi: 'Cụm danh từ chủ chốt trong tranh luận về điện hạt nhân.' },
      { phrase: 'variable output', meaningVi: 'sản lượng biến động', noteVi: 'Mô tả điện phụ thuộc điều kiện thời tiết.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-technology', topicSlug: 'technology', topicEn: 'Technology', topicVi: 'Công nghệ',
    title: 'Online courses and classroom learning',
    promptText: 'Some people believe online courses can replace most classroom teaching, while others think face-to-face education remains essential. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Digital courses have expanded access to lessons that once required attendance at a particular school or college. Some people expect this flexibility to replace much classroom teaching, while others value direct interaction. I believe online learning is an excellent supplement for many subjects, but schools should preserve in-person teaching for discussion, practical work and students who need structured support.', vi: 'Khoá học số mở rộng khả năng tiếp cận bài học vốn trước đây đòi hỏi phải đến một trường hay cao đẳng cụ thể. Một số người kỳ vọng sự linh hoạt này thay thế phần lớn việc dạy tại lớp, còn người khác coi trọng tương tác trực tiếp. Tôi cho rằng học trực tuyến bổ trợ rất tốt cho nhiều môn, nhưng trường học cần giữ dạy trực tiếp cho thảo luận, thực hành và học sinh cần hỗ trợ có cấu trúc.', focusVi: 'Mở bài trình bày quan điểm cân bằng và xác định vai trò mỗi hình thức.' },
      { en: 'Online courses allow learners to study at a suitable pace and revisit a difficult explanation as often as needed. Recorded lectures can serve students who live far from a campus, work irregular hours or require accessible captions. Institutions can also share specialist courses with a larger group than one classroom would hold. For factual material and independent revision, digital platforms may therefore be both convenient and cost-effective, especially when learners already possess the motivation to organise their time.', vi: 'Khoá học trực tuyến cho phép người học theo nhịp độ phù hợp và xem lại lời giải thích khó bao nhiêu lần tuỳ ý. Bài giảng ghi hình phục vụ sinh viên sống xa khu học xá, làm giờ thất thường hoặc cần phụ đề dễ tiếp cận. Cơ sở giáo dục cũng có thể chia sẻ môn chuyên sâu với nhóm lớn hơn sức chứa một lớp. Vì vậy, với kiến thức thực tế và ôn tập độc lập, nền tảng số có thể tiện lợi và tiết kiệm chi phí, nhất là khi người học đã có động lực sắp xếp thời gian.', focusVi: 'Thân bài 1 nêu lợi ích về linh hoạt, tiếp cận và khả năng mở rộng.' },
      { en: 'However, a screen cannot fully replace the immediate feedback and social cues of a classroom. A teacher can notice confusion, adjust an explanation and encourage a hesitant student to contribute. Practical subjects such as laboratory science also require equipment and supervision that are difficult to reproduce at home. Younger learners may struggle to stay focused without a timetable and peer group. A blended approach addresses these limits: online materials can deliver content, while classroom time is reserved for questions, collaboration and guided practice.', vi: 'Tuy nhiên, màn hình không thể thay thế hoàn toàn phản hồi tức thì và tín hiệu xã hội trong lớp. Giáo viên có thể nhận ra sự bối rối, điều chỉnh cách giải thích và khuyến khích học sinh ngập ngừng đóng góp. Môn thực hành như khoa học phòng thí nghiệm cũng cần thiết bị và giám sát khó tái tạo ở nhà. Người học nhỏ tuổi có thể khó tập trung nếu thiếu thời khoá biểu và nhóm bạn. Cách học kết hợp xử lý hạn chế này: tài liệu trực tuyến truyền tải nội dung, còn thời gian ở lớp dành cho câu hỏi, cộng tác và thực hành có hướng dẫn.', focusVi: 'Thân bài 2 trình bày lợi ích riêng của lớp học và cách phối hợp.' },
      { en: 'Online teaching can replace some lectures and revision activities, but not every educational experience. Face-to-face contact remains important where learners need feedback, equipment or a dependable routine. Combining the two formats makes education more flexible without sacrificing the human support that helps many students succeed.', vi: 'Dạy trực tuyến có thể thay một số bài giảng và hoạt động ôn tập, nhưng không thể thay mọi trải nghiệm giáo dục. Gặp trực tiếp vẫn quan trọng khi người học cần phản hồi, thiết bị hoặc nề nếp ổn định. Kết hợp hai hình thức khiến giáo dục linh hoạt hơn mà không đánh mất sự hỗ trợ con người giúp nhiều học sinh thành công.', focusVi: 'Kết luận xác định phần có thể thay thế và phần cần giữ trực tiếp.' },
    ],
    vocabulary: [
      { phrase: 'at a suitable pace', meaningVi: 'theo nhịp độ phù hợp', noteVi: 'Cụm thường dùng khi nói về học cá nhân hoá.' },
      { phrase: 'social cues', meaningVi: 'tín hiệu xã hội', noteVi: 'Ánh mắt, cử chỉ và phản ứng trong giao tiếp trực tiếp.' },
      { phrase: 'blended approach', meaningVi: 'cách tiếp cận kết hợp', noteVi: 'Mô hình phối hợp học trực tuyến và trực tiếp.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-health', topicSlug: 'health', topicEn: 'Health', topicVi: 'Sức khoẻ',
    title: 'Public or private health care',
    promptText: 'Some people believe health care should be provided mainly by public services, while others think private providers offer better care. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Health systems differ in how much they rely on public hospitals and private clinics. Supporters of public care emphasise universal access, whereas advocates of private provision value choice and shorter waits. In my opinion, public services should guarantee essential care for everyone, while regulated private providers can add capacity and choice without determining who receives treatment.', vi: 'Hệ thống y tế khác nhau về mức độ dựa vào bệnh viện công và phòng khám tư. Người ủng hộ dịch vụ công nhấn mạnh quyền tiếp cận toàn dân, còn người ủng hộ khu vực tư coi trọng lựa chọn và thời gian chờ ngắn. Theo tôi, dịch vụ công nên bảo đảm chăm sóc thiết yếu cho mọi người, trong khi cơ sở tư nhân được quản lý có thể bổ sung năng lực và lựa chọn mà không quyết định ai được điều trị.', focusVi: 'Mở bài nêu hai mô hình và xác định vai trò chính của hệ thống công.' },
      { en: 'Public provision spreads risk across society, so a person can receive emergency or long-term treatment regardless of income. It is also better placed to coordinate vaccination, disease surveillance and services in areas where private clinics may not be profitable. When funding is stable, public hospitals can plan staffing and specialist care for population needs rather than only for patients able to pay. These features make a strong public system important for fairness and for responding to health problems that affect entire communities.', vi: 'Dịch vụ công chia sẻ rủi ro trong toàn xã hội, nhờ đó một người có thể nhận điều trị cấp cứu hay dài hạn bất kể thu nhập. Hệ thống này cũng có vị thế tốt hơn để điều phối tiêm chủng, theo dõi bệnh tật và dịch vụ ở nơi phòng khám tư có thể không sinh lời. Khi kinh phí ổn định, bệnh viện công có thể hoạch định nhân sự và chăm sóc chuyên khoa theo nhu cầu dân số chứ không chỉ cho người có khả năng trả tiền. Những điểm này khiến hệ thống công vững mạnh quan trọng cho công bằng và ứng phó vấn đề sức khoẻ toàn cộng đồng.', focusVi: 'Thân bài 1 giải thích vì sao dịch vụ công cần bảo đảm quyền tiếp cận.' },
      { en: 'Private providers may offer more appointment times, specialised procedures or facilities that are unavailable in an overloaded public hospital. Competition can encourage innovation and give patients some control over where they receive non-urgent care. These advantages are real, but a system centred on ability to pay can widen health inequalities and draw scarce professionals away from public services. Regulation should therefore require transparent prices and safety standards, while public funding continues to cover treatment that people cannot reasonably purchase themselves.', vi: 'Cơ sở tư nhân có thể cung cấp nhiều khung giờ khám, thủ thuật chuyên biệt hay tiện nghi chưa có tại bệnh viện công quá tải. Cạnh tranh có thể khuyến khích đổi mới và cho bệnh nhân một phần quyền chọn nơi khám không khẩn cấp. Lợi ích này có thật, nhưng hệ thống dựa vào khả năng chi trả có thể làm bất bình đẳng sức khoẻ tăng và hút nhân lực khan hiếm khỏi dịch vụ công. Vì vậy, quy định cần yêu cầu giá minh bạch và tiêu chuẩn an toàn, còn ngân sách công tiếp tục chi trả điều trị mà người dân không thể tự mua hợp lý.', focusVi: 'Thân bài 2 công nhận ưu thế khu vực tư nhưng đặt giới hạn vì công bằng.' },
      { en: 'Public health care should remain the foundation because access to necessary treatment should not depend on personal wealth. Private providers can usefully expand services when their prices and standards are regulated. A mixed system is fair only if public capacity remains strong enough to serve people who have no alternative.', vi: 'Y tế công nên tiếp tục là nền tảng vì quyền tiếp cận điều trị cần thiết không nên phụ thuộc tài sản cá nhân. Cơ sở tư nhân có thể mở rộng dịch vụ hữu ích khi giá và tiêu chuẩn được quản lý. Hệ thống hỗn hợp chỉ công bằng nếu năng lực công đủ mạnh để phục vụ người không có lựa chọn khác.', focusVi: 'Kết luận tái khẳng định nền tảng công và điều kiện cho khu vực tư.' },
    ],
    vocabulary: [
      { phrase: 'spread risk across society', meaningVi: 'chia sẻ rủi ro trong toàn xã hội', noteVi: 'Cụm giải thích nguyên tắc bảo hiểm và chăm sóc công.' },
      { phrase: 'disease surveillance', meaningVi: 'giám sát dịch bệnh', noteVi: 'Hoạt động theo dõi và phát hiện xu hướng sức khoẻ cộng đồng.' },
      { phrase: 'health inequalities', meaningVi: 'bất bình đẳng về sức khoẻ', noteVi: 'Khác biệt về khả năng tiếp cận và kết quả y tế giữa các nhóm.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-society', topicSlug: 'society', topicEn: 'Society', topicVi: 'Xã hội',
    title: 'Living in cities or rural areas',
    promptText: 'Some people believe cities provide a better quality of life, while others prefer living in rural areas. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Where people live can shape their work, relationships and access to daily services. Cities offer density and variety, while rural areas are often valued for space and a slower pace. I do not think one setting is inherently superior; quality of life depends on whether residents can find suitable work, essential services and a community in either place.', vi: 'Nơi ở có thể định hình công việc, quan hệ và khả năng tiếp cận dịch vụ hằng ngày. Thành phố đem lại mật độ và sự đa dạng, còn vùng nông thôn thường được coi trọng vì không gian và nhịp sống chậm. Tôi không cho rằng môi trường nào vốn dĩ tốt hơn; chất lượng sống phụ thuộc vào việc cư dân có thể tìm việc phù hợp, dịch vụ thiết yếu và cộng đồng ở bất kỳ nơi nào.', focusVi: 'Mở bài trình bày hai lựa chọn và lập trường phụ thuộc hoàn cảnh.' },
      { en: 'City residents usually live closer to hospitals, colleges and a wider range of employers. Public transport and cultural venues can make it easier to study, change careers or meet people with different interests. For young adults and families without a car, this concentration of services may save time and open opportunities that are not available in a small settlement. Cities can therefore support social mobility when housing remains affordable and infrastructure keeps pace with population growth.', vi: 'Cư dân thành phố thường sống gần bệnh viện, trường cao đẳng và nhiều nhà tuyển dụng hơn. Giao thông công cộng và địa điểm văn hoá có thể giúp học tập, đổi nghề hoặc gặp người có sở thích khác nhau dễ hơn. Với người trẻ và gia đình không có ô tô, sự tập trung dịch vụ này có thể tiết kiệm thời gian và mở cơ hội không có ở khu định cư nhỏ. Vì vậy, thành phố có thể hỗ trợ dịch chuyển xã hội nếu nhà ở vẫn vừa túi tiền và hạ tầng theo kịp dân số.', focusVi: 'Thân bài 1 nêu lợi ích về dịch vụ, cơ hội và dịch chuyển xã hội của thành phố.' },
      { en: 'Rural residents may enjoy more space, lower noise and stronger connections with neighbours they know over many years. Access to nature can support recreation and wellbeing, while smaller communities may offer a sense of belonging that is harder to find in a large urban district. The drawback is that jobs, specialist health care and education may be far away. Remote work and mobile services can narrow this gap, but they need dependable internet and transport rather than optimistic promises.', vi: 'Cư dân nông thôn có thể tận hưởng không gian rộng, ít tiếng ồn và kết nối bền với hàng xóm quen biết nhiều năm. Tiếp cận thiên nhiên hỗ trợ giải trí và sức khoẻ, còn cộng đồng nhỏ có thể đem lại cảm giác gắn bó khó tìm ở khu đô thị lớn. Bất lợi là việc làm, chăm sóc y tế chuyên khoa và giáo dục có thể ở xa. Làm việc từ xa và dịch vụ lưu động có thể thu hẹp khoảng cách, nhưng cần internet và giao thông đáng tin chứ không phải lời hứa lạc quan.', focusVi: 'Thân bài 2 trình bày lợi ích nông thôn và thừa nhận giới hạn dịch vụ.' },
      { en: 'Cities are advantageous for access and choice, whereas rural life can offer space and close community ties. Neither guarantees wellbeing without affordable homes, transport and essential services. Governments should improve these conditions in both settings rather than assume that everyone should move towards one preferred model.', vi: 'Thành phố có lợi về tiếp cận và lựa chọn, trong khi đời sống nông thôn có thể đem lại không gian và quan hệ cộng đồng gần gũi. Không nơi nào bảo đảm sức khoẻ tốt nếu thiếu nhà ở vừa túi tiền, giao thông và dịch vụ thiết yếu. Chính phủ nên cải thiện các điều kiện này ở cả hai môi trường thay vì cho rằng mọi người nên chuyển đến một mô hình được ưa chuộng.', focusVi: 'Kết luận tổng hợp sự đánh đổi và nêu giải pháp chính sách hai phía.' },
    ],
    vocabulary: [
      { phrase: 'a wider range of employers', meaningVi: 'nhiều nhà tuyển dụng đa dạng hơn', noteVi: 'Cụm nói về độ phong phú của cơ hội việc làm.' },
      { phrase: 'sense of belonging', meaningVi: 'cảm giác gắn bó', noteVi: 'Cụm thường dùng về cộng đồng và bản sắc nơi chốn.' },
      { phrase: 'mobile services', meaningVi: 'dịch vụ lưu động', noteVi: 'Dịch vụ đi đến nhiều địa điểm thay vì tập trung một nơi.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-work', topicSlug: 'work', topicEn: 'Work', topicVi: 'Công việc',
    title: 'Rewarding seniority or performance',
    promptText: 'Some people believe employees should be rewarded mainly for their years of service, while others think pay and promotion should depend on performance. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Employers need fair ways to recognise contribution, but they differ over whether loyalty or results should carry more weight. Rewarding long service can value experience, while performance-based systems may encourage achievement. I believe tenure should inform decisions but should not determine them; clear evidence of contribution and opportunities to develop matter more.', vi: 'Nhà tuyển dụng cần cách công bằng để ghi nhận đóng góp, nhưng khác nhau ở việc lòng trung thành hay kết quả nên có trọng số cao hơn. Thưởng thâm niên coi trọng kinh nghiệm, còn hệ thống dựa trên hiệu suất có thể khuyến khích thành tích. Theo tôi, thời gian công tác nên được cân nhắc nhưng không quyết định tất cả; bằng chứng đóng góp rõ ràng và cơ hội phát triển quan trọng hơn.', focusVi:'Mở bài diễn đạt hai tiêu chí và nêu lập trường ưu tiên đóng góp.' },
      { en: 'Supporters of seniority argue that employees who remain with an organisation build knowledge that is difficult to replace. They may mentor new colleagues, understand customers and prevent mistakes because they recognise how a process has changed over time. Acknowledging service can also encourage retention in jobs where continuity matters, such as nursing or technical maintenance. If employers reward only visible short-term output, they may undervalue work that keeps the organisation functioning reliably but is harder to measure.', vi: 'Người ủng hộ thâm niên cho rằng nhân viên ở lại lâu năm tích luỹ kiến thức khó thay thế. Họ có thể hướng dẫn đồng nghiệp mới, hiểu khách hàng và ngăn lỗi vì nhận ra quy trình đã đổi theo thời gian. Ghi nhận thời gian cống hiến cũng khuyến khích giữ chân nhân sự ở công việc cần tính liên tục như điều dưỡng hay bảo trì kỹ thuật. Nếu chỉ thưởng kết quả ngắn hạn dễ thấy, nhà tuyển dụng có thể đánh giá thấp công việc giúp tổ chức vận hành ổn định nhưng khó đo lường.', focusVi:'Thân bài 1 giải thích vì sao thâm niên có thể phản ánh kiến thức và độ tin cậy.' },
      { en: 'Those who favour performance-based rewards say they make expectations clearer and recognise employees who take responsibility for difficult goals. A capable newcomer should not have to wait years for advancement simply because a more senior colleague arrived earlier. However, performance measures can be biased towards sales figures or individual tasks and overlook teamwork, care and mentoring. Employers should therefore use several indicators, invite review of decisions and explain what employees can do to progress instead of relying on a single ranking.', vi: 'Người ủng hộ thưởng theo hiệu suất cho rằng cách này làm kỳ vọng rõ hơn và ghi nhận nhân viên nhận trách nhiệm với mục tiêu khó. Người mới có năng lực không nên phải chờ nhiều năm chỉ vì đồng nghiệp thâm niên hơn đến trước. Tuy nhiên, chỉ số hiệu suất có thể thiên về doanh số hay nhiệm vụ cá nhân, bỏ qua cộng tác, chăm sóc và cố vấn. Vì vậy, nhà tuyển dụng nên dùng nhiều chỉ báo, cho phép xem xét quyết định và giải thích nhân viên cần làm gì để tiến bộ thay vì dựa vào một bảng xếp hạng.', focusVi:'Thân bài 2 nêu lợi ích và rủi ro của thưởng theo thành tích, rồi đề xuất đánh giá đa chiều.' },
      { en: 'Years of service can signal valuable experience, but automatic rewards may ignore differences in contribution. Employers should base advancement on transparent performance evidence while recognising mentoring and institutional knowledge that are not captured by simple targets. This approach rewards achievement without treating loyalty as irrelevant.', vi: 'Số năm công tác có thể cho thấy kinh nghiệm quý giá, nhưng thưởng tự động có thể bỏ qua khác biệt về đóng góp. Nhà tuyển dụng nên dựa vào bằng chứng hiệu suất minh bạch khi thăng tiến, đồng thời ghi nhận cố vấn và tri thức tổ chức không thể hiện qua chỉ tiêu đơn giản. Cách này thưởng thành tích mà không xem lòng trung thành là vô nghĩa.', focusVi:'Kết luận tổng hợp hai tiêu chí và đề xuất cách đánh giá cân bằng.' },
    ],
    vocabulary: [
      { phrase: 'institutional knowledge', meaningVi: 'tri thức tích luỹ trong tổ chức', noteVi: 'Hiểu biết về quy trình, con người và lịch sử của nơi làm việc.' },
      { phrase: 'short-term output', meaningVi: 'kết quả đầu ra ngắn hạn', noteVi: 'Chỉ số dễ thấy nhưng không phản ánh mọi đóng góp.' },
      { phrase: 'transparent performance evidence', meaningVi: 'bằng chứng hiệu suất minh bạch', noteVi: 'Cụm giúp diễn đạt cơ chế đánh giá công bằng.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-transport', topicSlug: 'transport', topicEn: 'Transport', topicVi: 'Giao thông',
    title: 'Pedestrian zones or central parking',
    promptText: 'Some people believe city centres should create more pedestrian-only streets, while others think convenient car parking is essential for businesses. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'City centres compete for visitors while trying to remain safe and accessible. Some people support streets reserved for pedestrians, whereas others worry that limiting parking will deter customers. I favour expanding pedestrian areas where public transport and delivery access are planned well, since a lively centre can attract people without requiring every visitor to arrive by car.', vi: 'Trung tâm thành phố cạnh tranh thu hút khách trong khi vẫn cần an toàn và dễ tiếp cận. Một số người ủng hộ phố chỉ dành cho người đi bộ, còn người khác lo hạn chế đỗ xe sẽ khiến khách hàng ngại đến. Tôi ủng hộ mở rộng khu đi bộ ở nơi đã quy hoạch tốt giao thông công cộng và tiếp cận giao hàng, vì trung tâm sôi động có thể thu hút mọi người mà không cần ai cũng đi ô tô.', focusVi:'Mở bài nêu hai phía và quan điểm ưu tiên không gian đi bộ nếu có kết nối phù hợp.' },
      { en: 'Pedestrian streets reduce conflict between vehicles and people on foot, making it safer for children and older residents to move around. Wider pavements can create room for outdoor seating, markets and street events that encourage visitors to stay longer. Businesses may gain from people browsing at walking speed rather than driving past. Clean air and lower noise also improve the experience for workers and residents who use the centre every day, not just shoppers who arrive at the weekend.', vi: 'Phố đi bộ giảm xung đột giữa xe cộ và người đi bộ, giúp trẻ em và cư dân lớn tuổi di chuyển an toàn hơn. Vỉa hè rộng tạo chỗ cho bàn ngoài trời, chợ và sự kiện đường phố khuyến khích khách nán lại lâu hơn. Doanh nghiệp có thể hưởng lợi khi mọi người đi dạo xem hàng thay vì lái xe vụt qua. Không khí sạch và tiếng ồn thấp cũng cải thiện trải nghiệm của nhân viên và cư dân dùng trung tâm hằng ngày, chứ không chỉ khách mua sắm cuối tuần.', focusVi:'Thân bài 1 giải thích lợi ích về an toàn, hoạt động thương mại và chất lượng môi trường.' },
      { en: 'Retailers argue that customers carrying large purchases or travelling from areas without public transport need nearby parking. Removing spaces too quickly can shift trade to out-of-town centres and make deliveries more complicated. These concerns can be addressed without giving cars unlimited access: cities can keep accessible bays, offer short-stay spaces at the edge of pedestrian zones and schedule freight deliveries outside busy hours. Clear transit information and reliable connections also matter; a walking street is only inclusive if people can reach it.', vi: 'Nhà bán lẻ cho rằng khách mang món hàng cồng kềnh hoặc đi từ nơi thiếu giao thông công cộng cần bãi đỗ gần. Xoá chỗ đỗ quá nhanh có thể chuyển hoạt động kinh doanh ra trung tâm ngoại ô và khiến giao hàng phức tạp hơn. Có thể giải quyết các lo ngại này mà không cho ô tô tiếp cận không giới hạn: thành phố giữ chỗ dễ tiếp cận, bố trí chỗ đỗ ngắn hạn ở rìa khu đi bộ và lên lịch giao hàng ngoài giờ đông. Thông tin giao thông rõ và kết nối tin cậy cũng quan trọng; phố đi bộ chỉ bao trùm nếu mọi người đến được đó.', focusVi:'Thân bài 2 trình bày nhu cầu đỗ xe và phương án dung hoà.' },
      { en: 'Pedestrian zones can improve safety and make city centres more attractive, but access for customers and deliveries must be designed carefully. A mix of edge parking, accessible spaces and good transit can address business concerns without surrendering every street to cars. This balance supports both commerce and public life.', vi: 'Khu đi bộ có thể cải thiện an toàn và khiến trung tâm hấp dẫn hơn, nhưng cần thiết kế cẩn thận lối tiếp cận cho khách và giao hàng. Kết hợp bãi đỗ ở rìa, chỗ tiếp cận thuận tiện và giao thông tốt có thể giải quyết lo ngại của doanh nghiệp mà không nhường mọi phố cho ô tô. Sự cân bằng này hỗ trợ cả thương mại lẫn đời sống công cộng.', focusVi:'Kết luận tái khẳng định ưu tiên đi bộ và nêu điều kiện hỗ trợ kinh doanh.' },
    ],
    vocabulary: [
      { phrase: 'pedestrian-only streets', meaningVi: 'đường phố chỉ dành cho người đi bộ', noteVi: 'Cụm danh từ mô tả khu vực cấm xe cơ giới thông thường.' },
      { phrase: 'short-stay spaces', meaningVi: 'chỗ đỗ xe ngắn hạn', noteVi: 'Vị trí phù hợp cho chuyến ghé mua hàng nhanh.' },
      { phrase: 'freight deliveries', meaningVi: 'việc giao hàng bằng xe vận tải', noteVi: 'Cụm dùng khi bàn về tiếp cận hậu cần.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-media', topicSlug: 'media', topicEn: 'Media', topicVi: 'Truyền thông',
    title: 'Public funding for news organisations',
    promptText: 'Some people believe news organisations should receive public funding to support independent journalism, while others think they should rely on commercial revenue. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'News organisations face declining print income while the public still needs reporting on local institutions and national decisions. Some people favour public funding to maintain coverage, whereas others fear political influence. I support limited, arm’s-length funding for public-interest journalism, provided that editorial independence and transparent oversight are protected.', vi: 'Cơ quan báo chí đối mặt với doanh thu in ấn giảm trong khi công chúng vẫn cần tin tức về tổ chức địa phương và quyết định quốc gia. Một số người ủng hộ tài trợ công để duy trì việc đưa tin, còn người khác lo ngại ảnh hưởng chính trị. Tôi ủng hộ khoản tài trợ giới hạn, độc lập cho báo chí vì lợi ích công, miễn là bảo vệ quyền tự chủ biên tập và giám sát minh bạch.', focusVi:'Mở bài trình bày tranh luận và nêu ủng hộ tài trợ có cơ chế độc lập.' },
      { en: 'Commercial revenue gives publishers an incentive to attract readers and can keep decision-making separate from government. Subscription models may build a direct relationship with audiences who value specialist investigations. Advertising can also support free access to news for people unable to pay. Yet commercial pressures often favour stories that generate quick clicks, while local councils or court hearings receive little attention. In areas with a small population, there may not be enough subscribers or advertisers to sustain a newsroom even when its reporting is essential.', vi: 'Doanh thu thương mại tạo động lực thu hút độc giả và có thể giữ quyết định biên tập tách khỏi chính phủ. Mô hình thuê bao xây dựng quan hệ trực tiếp với khán giả coi trọng điều tra chuyên sâu. Quảng cáo cũng hỗ trợ quyền tiếp cận tin miễn phí cho người không thể trả tiền. Tuy nhiên, áp lực thương mại thường ưu tiên tin tạo lượt nhấp nhanh, trong khi hội đồng địa phương hay phiên toà ít được chú ý. Ở khu dân cư nhỏ, có thể không đủ người đăng ký hay nhà quảng cáo để duy trì toà soạn dù tin tức đó thiết yếu.', focusVi:'Thân bài 1 trình bày ưu điểm doanh thu thị trường và giới hạn của nó.' },
      { en: 'Public funding can support coverage that produces social value without a large audience, such as reporting on remote regions or complex public budgets. It can also help maintain investigative teams that take months to verify a story. The risk is that officials may threaten to withdraw money after criticism. An independent fund with multi-year grants, published criteria and representatives from different sectors could reduce this danger. Public money should widen the range of journalism, not give ministers control over headlines.', vi: 'Tài trợ công có thể hỗ trợ tin tức tạo giá trị xã hội dù không có lượng khán giả lớn, như đưa tin về vùng xa hay ngân sách công phức tạp. Nó cũng giúp duy trì nhóm điều tra cần nhiều tháng xác minh câu chuyện. Rủi ro là quan chức có thể đe doạ rút kinh phí sau khi bị phê bình. Quỹ độc lập với khoản cấp nhiều năm, tiêu chí công khai và đại diện từ nhiều lĩnh vực có thể giảm nguy cơ này. Tiền công nên mở rộng sự đa dạng báo chí chứ không trao cho bộ trưởng quyền kiểm soát tiêu đề.', focusVi:'Thân bài 2 nêu lợi ích của tài trợ công và thiết kế bảo vệ độc lập.' },
      { en: 'Commercial income is valuable for independence, but it cannot sustain every form of reporting the public needs. Limited public grants can fill gaps if funding decisions are insulated from political pressure and audited openly. A mixed model is more resilient than relying on advertisers or government alone.', vi: 'Doanh thu thương mại có giá trị với tính độc lập, nhưng không thể duy trì mọi loại hình đưa tin công chúng cần. Khoản tài trợ công giới hạn có thể lấp khoảng trống nếu quyết định cấp tiền được cách ly khỏi áp lực chính trị và kiểm toán công khai. Mô hình hỗn hợp bền vững hơn phụ thuộc riêng vào nhà quảng cáo hay chính phủ.', focusVi:'Kết luận cân bằng hai nguồn và nhấn mạnh cơ chế độc lập.' },
    ],
    vocabulary: [
      { phrase: 'arm’s-length funding', meaningVi: 'tài trợ độc lập, không can thiệp trực tiếp', noteVi: 'Cụm chỉ khoảng cách giữa bên cấp tiền và quyết định biên tập.' },
      { phrase: 'editorial independence', meaningVi: 'tính độc lập biên tập', noteVi: 'Quyền quyết định nội dung của toà soạn.' },
      { phrase: 'insulated from political pressure', meaningVi: 'được cách ly khỏi áp lực chính trị', noteVi: 'Cách diễn đạt về cơ chế bảo vệ tổ chức.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-crime', topicSlug: 'crime', topicEn: 'Crime', topicVi: 'Tội phạm',
    title: 'Cameras in public places and privacy',
    promptText: 'Some people believe more surveillance cameras make public places safer, while others think they threaten privacy. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Cameras are now common in transport hubs, shopping areas and residential streets. Supporters see them as a way to deter offences and identify suspects, whereas critics worry about constant monitoring. I support limited camera use in locations with a clear safety need, but only under rules that restrict access, retention and secondary use of footage.', vi: 'Camera hiện phổ biến ở đầu mối giao thông, khu mua sắm và phố dân cư. Người ủng hộ xem chúng là cách ngăn vi phạm và nhận diện nghi phạm, còn người chỉ trích lo ngại bị theo dõi liên tục. Tôi ủng hộ sử dụng camera giới hạn ở nơi có nhu cầu an toàn rõ ràng, nhưng chỉ khi có quy tắc hạn chế truy cập, lưu trữ và mục đích sử dụng hình ảnh thứ cấp.', focusVi:'Mở bài nêu lợi ích, lo ngại và lập trường ủng hộ có kiểm soát.' },
      { en: 'Visible cameras may discourage opportunistic theft or vandalism because a person knows their actions could be recorded. When an offence does occur, footage can help investigators establish the sequence of events and protect an innocent person from a mistaken accusation. Cameras are especially useful in transport stations or car parks where incidents may otherwise have no witnesses. For residents, the perception that a public space is monitored can make it feel safer at night, although this effect depends on how quickly staff respond to a problem.', vi: 'Camera dễ thấy có thể ngăn trộm vặt hay phá hoại cơ hội vì người ta biết hành động có thể được ghi lại. Khi vi phạm xảy ra, hình ảnh giúp điều tra viên xác lập trình tự sự việc và bảo vệ người vô tội khỏi cáo buộc nhầm. Camera đặc biệt hữu ích ở ga giao thông hay bãi đỗ xe nơi có thể không có nhân chứng. Với cư dân, cảm giác không gian công cộng được giám sát có thể khiến họ thấy an toàn hơn vào ban đêm, dù hiệu quả phụ thuộc vào tốc độ nhân viên phản hồi sự cố.', focusVi:'Thân bài 1 giải thích tác dụng phòng ngừa, điều tra và cảm nhận an toàn.' },
      { en: 'The opposing concern is that recorded movement can reveal private routines, and footage may be accessed for purposes unrelated to public safety. A camera network can also be expanded gradually without open discussion, leaving residents unsure who is watching them. Clear safeguards are therefore essential: publish camera locations, restrict searches to authorised cases, delete footage after a short period and audit access logs. Cameras should not substitute for lighting, staff presence or community services that address the causes of insecurity.', vi: 'Lo ngại đối lập là hành trình được ghi lại có thể tiết lộ thói quen riêng tư, còn hình ảnh có thể bị truy cập vì mục đích không liên quan đến an toàn công cộng. Mạng camera cũng có thể được mở rộng dần mà thiếu thảo luận công khai, khiến cư dân không biết ai đang theo dõi mình. Vì vậy, cần bảo đảm rõ ràng: công bố vị trí camera, giới hạn tìm kiếm vào vụ việc được phép, xoá hình ảnh sau thời gian ngắn và kiểm toán nhật ký truy cập. Camera không nên thay thế chiếu sáng, nhân viên hiện diện hay dịch vụ cộng đồng giải quyết nguyên nhân mất an toàn.', focusVi:'Thân bài 2 nêu nguy cơ quyền riêng tư và các giới hạn cần thiết.' },
      { en: 'Surveillance can assist safety when cameras are targeted and footage is handled responsibly. It becomes an unjustified intrusion when recording is broad, indefinite or invisible to the public. Clear oversight and investment in non-surveillance safety measures can protect both security and privacy.', vi: 'Giám sát có thể hỗ trợ an toàn khi camera được đặt có mục tiêu và hình ảnh được xử lý có trách nhiệm. Nó trở thành xâm phạm không chính đáng khi ghi hình quá rộng, vô thời hạn hoặc không được công chúng biết đến. Giám sát rõ ràng và đầu tư vào biện pháp an toàn không cần theo dõi có thể bảo vệ cả an ninh lẫn quyền riêng tư.', focusVi:'Kết luận phân định trường hợp sử dụng hợp lý và nhấn mạnh giám sát.' },
    ],
    vocabulary: [
      { phrase: 'deter opportunistic theft', meaningVi: 'ngăn hành vi trộm cắp cơ hội', noteVi: 'Cụm động từ mô tả tác dụng phòng ngừa.' },
      { phrase: 'retention period', meaningVi: 'thời hạn lưu trữ', noteVi: 'Khoảng thời gian dữ liệu được giữ lại.' },
      { phrase: 'access logs', meaningVi: 'nhật ký truy cập', noteVi: 'Bản ghi cho biết ai đã xem hoặc sử dụng dữ liệu.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-government', topicSlug: 'government', topicEn: 'Government', topicVi: 'Chính phủ',
    title: 'Lower taxes or stronger public services',
    promptText: 'Some people believe governments should reduce taxes so individuals can keep more of their earnings, while others think taxes should fund stronger public services. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Tax policy affects both household budgets and the services people rely on. Those who favour lower taxes emphasise personal choice and incentives, while supporters of higher public spending stress shared provision. I believe tax levels should be sufficient to fund reliable essential services, with the burden distributed fairly and spending evaluated openly.', vi: 'Chính sách thuế ảnh hưởng cả ngân sách hộ gia đình lẫn dịch vụ người dân dựa vào. Người ủng hộ thuế thấp nhấn mạnh quyền lựa chọn cá nhân và động lực làm việc, còn người ủng hộ chi công cao coi trọng dịch vụ chung. Tôi cho rằng mức thuế cần đủ để tài trợ dịch vụ thiết yếu đáng tin cậy, với gánh nặng phân bổ công bằng và chi tiêu được đánh giá công khai.', focusVi:'Mở bài trình bày hai phía và xác định tiêu chí về mức dịch vụ, công bằng.' },
      { en: 'Lower taxes leave households with more disposable income, which can help families pay for housing, education or savings. Businesses may also retain more capital to hire staff or invest in equipment. When tax rates are high but public services are inefficient, citizens can reasonably question whether the money is being used well. Supporters therefore argue that reducing rates can stimulate private activity and give people greater control over decisions that affect their own lives.', vi: 'Thuế thấp để hộ gia đình giữ nhiều thu nhập khả dụng hơn, giúp chi trả nhà ở, giáo dục hay tiết kiệm. Doanh nghiệp cũng có thể giữ thêm vốn để tuyển người hoặc đầu tư thiết bị. Khi thuế cao nhưng dịch vụ công kém hiệu quả, công dân có lý do để đặt câu hỏi tiền được sử dụng tốt hay không. Vì vậy, người ủng hộ cho rằng giảm thuế có thể thúc đẩy hoạt động tư nhân và trao cho mọi người quyền kiểm soát lớn hơn với lựa chọn ảnh hưởng đến đời mình.', focusVi:'Thân bài 1 giải thích lập luận về thu nhập, đầu tư và quyền lựa chọn.' },
      { en: 'Higher revenue can support schools, public transport and health care that households would struggle to buy individually. These services also benefit businesses by producing a healthy, educated workforce and connecting employees with jobs. If provision is inadequate, private spending may rise but access will depend more heavily on income. The argument for taxes is strongest when public programmes are transparent and reach people effectively; wasteful spending weakens trust and should be corrected rather than ignored.', vi: 'Nguồn thu cao hơn có thể hỗ trợ trường học, giao thông công cộng và chăm sóc y tế mà từng hộ khó tự mua. Các dịch vụ này cũng có lợi cho doanh nghiệp nhờ tạo lực lượng lao động khoẻ mạnh, được giáo dục và kết nối người lao động với việc làm. Nếu dịch vụ thiếu hụt, chi tư nhân có thể tăng nhưng khả năng tiếp cận phụ thuộc nhiều hơn vào thu nhập. Lập luận cho thuế thuyết phục nhất khi chương trình công minh bạch và đến được người cần; chi tiêu lãng phí làm suy giảm niềm tin và cần được khắc phục thay vì bỏ qua.', focusVi:'Thân bài 2 giải thích lợi ích của nguồn thu chung và điều kiện tạo niềm tin.' },
      { en: 'Low taxes can support choice and investment, but they are not valuable if households must replace essential services privately. A fair tax system should fund dependable public provision and disclose how revenue is used. The debate is therefore about both the level of taxation and the quality of government spending.', vi: 'Thuế thấp có thể hỗ trợ lựa chọn và đầu tư, nhưng không có nhiều giá trị nếu hộ gia đình phải tự mua dịch vụ thiết yếu. Hệ thống thuế công bằng cần tài trợ dịch vụ công đáng tin cậy và công khai cách sử dụng nguồn thu. Vì vậy, tranh luận liên quan cả mức thuế lẫn chất lượng chi tiêu của chính phủ.', focusVi:'Kết luận tổng hợp hai phía và nhấn mạnh trách nhiệm giải trình.' },
    ],
    vocabulary: [
      { phrase: 'disposable income', meaningVi: 'thu nhập khả dụng', noteVi: 'Khoản còn lại sau thuế và nghĩa vụ bắt buộc.' },
      { phrase: 'public provision', meaningVi: 'dịch vụ do nhà nước cung cấp', noteVi: 'Cụm khái quát trường học, y tế và dịch vụ chung.' },
      { phrase: 'tax revenue', meaningVi: 'nguồn thu thuế', noteVi: 'Cụm thường dùng trong tranh luận ngân sách.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-culture', topicSlug: 'culture', topicEn: 'Culture', topicVi: 'Văn hoá',
    title: 'Global languages or local languages in school',
    promptText: 'Some people believe schools should prioritise international languages, while others think local languages deserve more teaching time. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Schools have limited time to teach languages, yet students need both wider communication and a connection to their community. Some people favour international languages for study and work, while others want local languages protected. I believe pupils should gain strong competence in a widely used language without allowing local languages to disappear from education.', vi: 'Trường học có thời lượng dạy ngôn ngữ hạn chế, nhưng học sinh cần cả khả năng giao tiếp rộng lẫn kết nối với cộng đồng. Một số người ưu tiên ngôn ngữ quốc tế cho học tập và việc làm, còn người khác muốn bảo vệ ngôn ngữ địa phương. Tôi cho rằng học sinh nên thành thạo một ngôn ngữ được sử dụng rộng rãi mà không để ngôn ngữ địa phương biến mất khỏi giáo dục.', focusVi:'Mở bài nêu cả nhu cầu giao tiếp toàn cầu và bảo tồn bản sắc.' },
      { en: 'An international language can open access to universities, research and employers beyond a student’s home region. It allows young people to participate in exchange programmes and communicate with people from different countries. In economies where tourism or trade is important, language skills can also improve local employment prospects. Parents may therefore reasonably expect schools to prioritise a language that offers their children practical opportunities, especially when private lessons are too expensive for many families.', vi: 'Ngôn ngữ quốc tế có thể mở lối đến đại học, nghiên cứu và nhà tuyển dụng ngoài khu vực quê nhà. Nó cho phép người trẻ tham gia chương trình trao đổi và giao tiếp với người từ quốc gia khác. Ở nền kinh tế quan trọng về du lịch hay thương mại, kỹ năng ngôn ngữ còn cải thiện triển vọng việc làm địa phương. Vì vậy, cha mẹ có thể kỳ vọng hợp lý trường ưu tiên ngôn ngữ đem lại cơ hội thiết thực cho con, đặc biệt khi nhiều gia đình không đủ tiền học tư.', focusVi:'Thân bài 1 giải thích lợi ích cơ hội của ngôn ngữ quốc tế.' },
      { en: 'Local languages carry stories, ecological knowledge and ways of expressing relationships that may not translate neatly into a global language. When children cannot read or speak them, communication with older relatives may weaken and cultural practices can become harder to pass on. Protecting a local language does not require every subject to be taught through it; schools can offer dedicated lessons, community projects and bilingual materials. This preserves heritage while leaving room for students to learn languages that connect them internationally.', vi: 'Ngôn ngữ địa phương lưu giữ câu chuyện, tri thức sinh thái và cách thể hiện quan hệ có thể không dịch trọn vẹn sang ngôn ngữ toàn cầu. Khi trẻ không thể đọc hay nói các ngôn ngữ ấy, giao tiếp với người thân lớn tuổi có thể yếu đi và tập quán văn hoá khó truyền lại hơn. Bảo vệ ngôn ngữ địa phương không đòi hỏi dạy mọi môn bằng ngôn ngữ đó; trường có thể mở tiết riêng, dự án cộng đồng và tài liệu song ngữ. Cách này giữ di sản mà vẫn để học sinh học ngôn ngữ kết nối quốc tế.', focusVi:'Thân bài 2 nêu giá trị bản sắc và cách bảo tồn mà không hy sinh cơ hội.' },
      { en: 'International languages can expand education and employment choices, while local languages protect belonging and shared knowledge. Schools should guarantee meaningful teaching in both, adjusting time to the needs of their pupils and community. This approach treats multilingual ability as an advantage rather than a competition between identities.', vi: 'Ngôn ngữ quốc tế mở rộng lựa chọn học tập và việc làm, còn ngôn ngữ địa phương bảo vệ sự gắn bó và tri thức chung. Trường học nên bảo đảm việc dạy có ý nghĩa cho cả hai, điều chỉnh thời lượng theo nhu cầu học sinh và cộng đồng. Cách tiếp cận này xem năng lực đa ngôn ngữ là lợi thế thay vì cuộc cạnh tranh giữa các bản sắc.', focusVi:'Kết luận cân bằng hai chức năng và chốt cách nhìn đa ngôn ngữ.' },
    ],
    vocabulary: [
      { phrase: 'employment prospects', meaningVi: 'triển vọng việc làm', noteVi: 'Cụm danh từ thường dùng trong chủ đề giáo dục và nghề nghiệp.' },
      { phrase: 'ecological knowledge', meaningVi: 'tri thức sinh thái', noteVi: 'Kiến thức địa phương về môi trường và hệ sinh thái.' },
      { phrase: 'bilingual materials', meaningVi: 'tài liệu song ngữ', noteVi: 'Nguồn học liệu trình bày nội dung bằng hai ngôn ngữ.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-tourism', topicSlug: 'tourism', topicEn: 'Tourism', topicVi: 'Du lịch',
    title: 'Promoting domestic or international tourism',
    promptText: 'Some people think governments should encourage domestic tourism, while others believe attracting international visitors is more important. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Tourism policy can focus on residents exploring their own country or on visitors arriving from abroad. Domestic travel may spread spending more evenly and be less vulnerable to global disruption, while international tourism brings outside income. I believe governments should build a resilient domestic base while attracting international visitors selectively, rather than treating either market as the sole priority.', vi: 'Chính sách du lịch có thể tập trung vào cư dân khám phá đất nước mình hoặc khách từ nước ngoài đến. Du lịch nội địa có thể phân bổ chi tiêu đều hơn và ít dễ tổn thương trước biến động toàn cầu, còn du lịch quốc tế đem nguồn thu từ bên ngoài. Tôi cho rằng chính phủ nên xây nền nội địa vững đồng thời chọn lọc thu hút khách quốc tế, thay vì xem một thị trường nào là ưu tiên duy nhất.', focusVi:'Mở bài nêu hai thị trường và lập trường đa dạng hoá.' },
      { en: 'Encouraging residents to travel domestically supports regional businesses and helps families discover places that receive little international attention. People may visit outside peak seasons, giving small hotels and transport operators steadier income across the year. Domestic tourism also allows governments to promote local heritage to their own population and can keep travel spending circulating within the national economy. It is often easier to maintain demand when residents can take shorter trips and are not dependent on long-haul flights.', vi: 'Khuyến khích cư dân du lịch trong nước hỗ trợ doanh nghiệp vùng và giúp gia đình khám phá nơi ít được khách quốc tế chú ý. Mọi người có thể đi ngoài mùa cao điểm, đem thu nhập ổn định hơn quanh năm cho khách sạn nhỏ và đơn vị vận tải. Du lịch nội địa còn cho phép chính phủ giới thiệu di sản cho chính người dân và giữ chi tiêu lưu thông trong nền kinh tế quốc gia. Việc duy trì nhu cầu thường dễ hơn khi cư dân có thể đi chuyến ngắn và không phụ thuộc vào chuyến bay đường dài.', focusVi:'Thân bài 1 giải thích lợi ích phân bổ và tính ổn định của du lịch nội địa.' },
      { en: 'International visitors can spend foreign income in local restaurants, accommodation and cultural attractions. They may support specialist guides and preserve sites that would be costly for local taxpayers to maintain alone. However, an economy dependent on overseas arrivals is vulnerable to travel restrictions, currency shifts and global crises. Destinations should therefore seek visitors who stay longer and engage with local businesses, while ensuring that housing and public spaces remain usable for residents. Quality and local benefit matter more than simply maximising arrival numbers.', vi: 'Khách quốc tế có thể chi ngoại tệ tại nhà hàng, nơi lưu trú và điểm văn hoá địa phương. Họ có thể hỗ trợ hướng dẫn viên chuyên ngành và bảo tồn di tích mà người đóng thuế địa phương khó tự duy trì. Tuy nhiên, nền kinh tế phụ thuộc vào khách nước ngoài dễ bị tổn thương trước hạn chế đi lại, biến động tiền tệ và khủng hoảng toàn cầu. Vì vậy, điểm đến nên thu hút khách ở lâu và sử dụng doanh nghiệp địa phương, đồng thời bảo đảm nhà ở và không gian công cộng vẫn phục vụ cư dân. Chất lượng và lợi ích địa phương quan trọng hơn tối đa hoá số lượt đến.', focusVi:'Thân bài 2 nêu lợi ích nguồn thu quốc tế và rủi ro phụ thuộc.' },
      { en: 'Domestic tourism offers resilience and broad participation, while international travel can inject new income and sustain specialised attractions. Governments should support both markets with standards that protect residents and local businesses. A diversified visitor economy is less exposed to sudden changes than one built around a single source of demand.', vi: 'Du lịch nội địa đem lại sức chống chịu và sự tham gia rộng, còn khách quốc tế có thể mang nguồn thu mới và duy trì điểm tham quan chuyên biệt. Chính phủ nên hỗ trợ cả hai thị trường bằng tiêu chuẩn bảo vệ cư dân và doanh nghiệp địa phương. Nền kinh tế du khách đa dạng ít bị tác động bởi biến động bất ngờ hơn mô hình chỉ dựa vào một nguồn cầu.', focusVi:'Kết luận tổng hợp lợi ích và tái khẳng định chiến lược đa dạng.' },
    ],
    vocabulary: [
      { phrase: 'domestic tourism', meaningVi: 'du lịch nội địa', noteVi: 'Hoạt động du lịch của cư dân trong nước.' },
      { phrase: 'foreign income', meaningVi: 'nguồn thu từ nước ngoài', noteVi: 'Khoản chi của du khách quốc tế trong nền kinh tế địa phương.' },
      { phrase: 'diversified visitor economy', meaningVi: 'nền kinh tế du khách đa dạng', noteVi: 'Cụm mô tả nguồn khách và dịch vụ phong phú.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-science', topicSlug: 'science', topicEn: 'Science', topicVi: 'Khoa học',
    title: 'Animal testing or computer models',
    promptText: 'Some people believe animal testing is sometimes necessary for medical research, while others think computer models and other alternatives should replace it. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Researchers need evidence that a treatment is safe before it reaches patients, but the methods used to obtain that evidence are ethically contested. Some people accept limited animal testing, whereas others argue that alternatives should replace it. I believe research should use non-animal methods wherever they are scientifically adequate, with tightly regulated animal studies permitted only when no reliable substitute exists.', vi: 'Nhà nghiên cứu cần bằng chứng điều trị an toàn trước khi áp dụng cho bệnh nhân, nhưng phương pháp thu thập bằng chứng gây tranh luận đạo đức. Một số người chấp nhận thử nghiệm động vật giới hạn, còn người khác cho rằng nên thay bằng phương pháp khác. Tôi cho rằng cần dùng phương pháp không động vật ở nơi chúng đủ cơ sở khoa học, chỉ cho phép thử nghiệm động vật được quản lý nghiêm khi không có lựa chọn thay thế đáng tin cậy.', focusVi:'Mở bài trình bày tranh luận và đặt nguyên tắc giảm thiểu có điều kiện.' },
      { en: 'Supporters of animal studies argue that a living organism can reveal interactions between organs that a computer model may not yet reproduce. Before a new medicine is given to people, researchers need to understand possible toxicity and how a whole body responds. Historical medical advances have sometimes depended on such evidence, and abandoning it immediately could slow the development of treatments for serious diseases. This argument is strongest when the research addresses a substantial health need and the study is carefully designed to use as few animals as possible.', vi: 'Người ủng hộ nghiên cứu trên động vật cho rằng cơ thể sống có thể bộc lộ tương tác giữa các cơ quan mà mô hình máy tính chưa tái tạo được. Trước khi dùng thuốc mới cho người, nhà nghiên cứu cần hiểu độc tính tiềm tàng và phản ứng của toàn cơ thể. Một số tiến bộ y học trong quá khứ dựa vào bằng chứng này, và từ bỏ ngay có thể làm chậm phát triển điều trị bệnh nghiêm trọng. Lập luận thuyết phục nhất khi nghiên cứu đáp ứng nhu cầu sức khoẻ lớn và được thiết kế kỹ để dùng ít động vật nhất có thể.', focusVi:'Thân bài 1 trình bày lý do khoa học cho thử nghiệm có giới hạn.' },
      { en: 'Opponents point out that animals experience pain and that results from one species do not always predict human outcomes. Cell cultures, organ-on-chip systems and computer simulations are improving, sometimes offering more relevant information while avoiding animal suffering. Investment in these alternatives may accelerate innovation instead of merely replacing an existing practice. However, models also have limits and must be validated against evidence. Research authorities should require a review of alternatives, independent ethical oversight and public reporting of why an animal study remains necessary.', vi: 'Người phản đối chỉ ra động vật cảm nhận đau đớn và kết quả ở một loài không phải lúc nào cũng dự đoán được kết quả ở người. Nuôi cấy tế bào, mô hình cơ quan trên chip và mô phỏng máy tính đang cải thiện, đôi khi cung cấp thông tin liên quan hơn mà tránh đau đớn cho động vật. Đầu tư vào lựa chọn thay thế có thể thúc đẩy đổi mới thay vì chỉ thay một tập quán hiện có. Tuy nhiên, mô hình cũng có giới hạn và phải được kiểm chứng. Cơ quan nghiên cứu cần yêu cầu rà soát phương án khác, giám sát đạo đức độc lập và công khai lý do nghiên cứu động vật còn cần thiết.', focusVi:'Thân bài 2 trình bày quan điểm đạo đức, tiến bộ thay thế và cơ chế kiểm soát.' },
      { en: 'Medical evidence must be reliable, but animal use should not remain the default when better methods exist. Funding alternatives and reviewing every proposed study can reduce suffering without weakening research standards. Animal testing is defensible only as a last resort for important questions that cannot yet be answered another way.', vi: 'Bằng chứng y tế phải đáng tin cậy, nhưng sử dụng động vật không nên là lựa chọn mặc định khi có phương pháp tốt hơn. Tài trợ lựa chọn thay thế và rà soát từng nghiên cứu có thể giảm đau đớn mà không làm yếu tiêu chuẩn nghiên cứu. Thử nghiệm động vật chỉ chính đáng như giải pháp cuối cùng cho câu hỏi quan trọng chưa thể trả lời theo cách khác.', focusVi:'Kết luận khẳng định nguyên tắc lựa chọn thay thế trước và điều kiện ngoại lệ.' },
    ],
    vocabulary: [
      { phrase: 'whole-body response', meaningVi: 'phản ứng của toàn cơ thể', noteVi: 'Cụm phân biệt nghiên cứu hệ thống với mô hình đơn lẻ.' },
      { phrase: 'organ-on-chip systems', meaningVi: 'hệ thống mô phỏng cơ quan trên chip', noteVi: 'Công nghệ nghiên cứu sinh học thay thế một phần thử nghiệm.' },
      { phrase: 'ethical oversight', meaningVi: 'giám sát đạo đức', noteVi: 'Cơ chế đánh giá tính chính đáng của nghiên cứu.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-family', topicSlug: 'family', topicEn: 'Family', topicVi: 'Gia đình',
    title: 'Parents or children choosing activities',
    promptText: 'Some people believe parents should choose children’s after-school activities, while others think children should make these decisions themselves. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'After-school activities can shape children’s interests, friendships and use of free time. Parents may want to guide choices based on safety and development, while children value having a say in what they do. I believe adults should set reasonable limits and provide options, but children should increasingly choose activities as their interests and maturity develop.', vi: 'Hoạt động sau giờ học có thể định hình sở thích, tình bạn và cách trẻ sử dụng thời gian rảnh. Cha mẹ có thể muốn hướng dẫn lựa chọn dựa trên an toàn và sự phát triển, còn trẻ coi trọng việc được quyết định mình làm gì. Tôi cho rằng người lớn nên đặt giới hạn hợp lý và cung cấp lựa chọn, nhưng trẻ cần dần tự chọn hoạt động khi sở thích và sự trưởng thành phát triển.', focusVi:'Mở bài nêu hai góc nhìn và lập trường tăng quyền tự quyết theo độ tuổi.' },
      { en: 'Parents are responsible for ensuring that activities are safe, affordable and compatible with school responsibilities. A child may not understand the travel time, equipment costs or commitment involved in joining a competitive team. Adults can also introduce opportunities the child has not encountered, such as music lessons or volunteering. Their guidance is particularly valuable for younger children, who may choose an activity because a friend is doing it without knowing whether it suits them.', vi: 'Cha mẹ chịu trách nhiệm bảo đảm hoạt động an toàn, vừa túi tiền và phù hợp với việc học. Trẻ có thể chưa hiểu thời gian đi lại, chi phí thiết bị hay mức cam kết khi tham gia đội thi đấu. Người lớn cũng có thể giới thiệu cơ hội trẻ chưa từng biết, như học nhạc hay tình nguyện. Sự hướng dẫn đặc biệt có ích với trẻ nhỏ, vốn có thể chọn hoạt động chỉ vì bạn tham gia mà chưa biết nó có hợp mình không.', focusVi:'Thân bài 1 giải thích lý do cha mẹ cần hướng dẫn và cân nhắc điều kiện thực tế.' },
      { en: 'Children should nevertheless have a meaningful choice because motivation is difficult to impose. A young person who selects a sport or creative activity is more likely to practise regularly and persist when it becomes challenging. Choice also helps children discover their strengths and learn to manage time. Parents can prevent overscheduling by agreeing on a manageable number of commitments, then letting the child choose among suitable options. This approach keeps adult judgement about safety while giving the young person genuine ownership.', vi: 'Dù vậy, trẻ nên có quyền lựa chọn thực chất vì động lực khó áp đặt. Người trẻ tự chọn môn thể thao hay hoạt động sáng tạo có khả năng luyện tập thường xuyên và kiên trì hơn khi gặp thử thách. Quyền lựa chọn cũng giúp trẻ khám phá điểm mạnh và học quản lý thời gian. Cha mẹ có thể ngăn lịch quá tải bằng cách thống nhất số lượng cam kết vừa sức, rồi để trẻ chọn trong các phương án phù hợp. Cách này giữ vai trò phán đoán an toàn của người lớn, đồng thời trao cho trẻ quyền làm chủ thực sự.', focusVi:'Thân bài 2 nêu lợi ích của quyền lựa chọn và mô hình chia sẻ quyết định.' },
      { en: 'Parents should guide the boundaries, but children should influence the choice within them. The balance can shift gradually as a child becomes better able to judge time, cost and personal interest. Shared decisions are more likely to produce activities that are safe, sustainable and genuinely enjoyable.', vi: 'Cha mẹ nên hướng dẫn các giới hạn, nhưng trẻ cần có tiếng nói trong lựa chọn bên trong những giới hạn ấy. Sự cân bằng có thể dịch chuyển dần khi trẻ biết đánh giá thời gian, chi phí và sở thích cá nhân tốt hơn. Quyết định chung có khả năng tạo ra hoạt động an toàn, bền vững và thực sự thú vị hơn.', focusVi:'Kết luận chốt nguyên tắc chia sẻ quyết định và điều chỉnh theo độ trưởng thành.' },
    ],
    vocabulary: [
      { phrase: 'compatible with', meaningVi: 'phù hợp với', noteVi: 'Cấu trúc dùng khi cân nhắc hai lịch trình hoặc yêu cầu.' },
      { phrase: 'persist when challenging', meaningVi: 'kiên trì khi gặp thử thách', noteVi: 'Cụm động từ mô tả động lực nội tại.' },
      { phrase: 'genuine ownership', meaningVi: 'quyền làm chủ thực sự', noteVi: 'Cụm nhấn mạnh trẻ có vai trò quyết định chứ không chỉ được hỏi ý kiến.' },
    ],
  },
  {
    id: 'sample-t2-extra-discussion2-economy', topicSlug: 'economy', topicEn: 'Economy', topicVi: 'Kinh tế',
    title: 'Free trade or protecting local industries',
    promptText: 'Some people believe countries benefit from free trade, while others think governments should protect local industries from foreign competition. Discuss both views and give your own opinion.',
    paragraphs: [
      { en: 'Countries must decide how openly their firms should compete with producers abroad. Free-trade supporters emphasise lower prices and access to larger markets, while protectionists want to preserve domestic jobs and skills. I support open trade in general, combined with temporary and targeted assistance for industries that are strategically important or facing an unfair adjustment burden.', vi: 'Các quốc gia phải quyết định doanh nghiệp trong nước cạnh tranh với nhà sản xuất nước ngoài cởi mở đến đâu. Người ủng hộ thương mại tự do nhấn mạnh giá thấp và khả năng tiếp cận thị trường lớn, còn người bảo hộ muốn giữ việc làm và kỹ năng trong nước. Tôi nhìn chung ủng hộ thương mại mở, kết hợp hỗ trợ tạm thời, có mục tiêu cho ngành chiến lược hoặc đang chịu gánh nặng chuyển đổi bất công.', focusVi:'Mở bài nêu hai mục tiêu kinh tế và lập trường ủng hộ mở cửa có hỗ trợ.' },
      { en: 'Open trade allows consumers to choose from more goods, often at lower prices, and gives firms the chance to sell beyond a limited domestic market. Competition can encourage producers to improve quality and adopt efficient methods. Export industries may also create specialised jobs that depend on international demand. For smaller economies, access to overseas customers can support growth that would be impossible if every firm served only local buyers. These benefits are strongest when workers can move into new opportunities as industries change.', vi: 'Thương mại mở cho người tiêu dùng nhiều lựa chọn hơn, thường với giá thấp hơn, và giúp doanh nghiệp bán ra ngoài thị trường nội địa hạn chế. Cạnh tranh có thể khuyến khích nhà sản xuất cải thiện chất lượng và áp dụng phương pháp hiệu quả. Ngành xuất khẩu cũng có thể tạo việc làm chuyên môn phụ thuộc vào nhu cầu quốc tế. Với nền kinh tế nhỏ, tiếp cận khách hàng nước ngoài hỗ trợ tăng trưởng khó đạt được nếu mọi công ty chỉ phục vụ người mua trong nước. Lợi ích này lớn nhất khi người lao động có thể chuyển sang cơ hội mới lúc ngành nghề thay đổi.', focusVi:'Thân bài 1 giải thích lợi ích của thương mại tự do cho người mua và doanh nghiệp.' },
      { en: 'Those favouring protection argue that sudden import competition can close factories before a region has time to develop alternatives. A country may also wish to retain capacity in areas such as medicines or food processing, where supply disruption could threaten security. However, permanent protection can keep inefficient firms alive and raise costs for households. Governments should identify a clear public purpose, set a review date and fund retraining or regional investment rather than shielding every producer from competition indefinitely.', vi: 'Người ủng hộ bảo hộ cho rằng cạnh tranh nhập khẩu đột ngột có thể đóng cửa nhà máy trước khi khu vực kịp phát triển lựa chọn khác. Quốc gia cũng có thể muốn giữ năng lực trong lĩnh vực như dược phẩm hay chế biến thực phẩm, nơi gián đoạn nguồn cung đe doạ an ninh. Tuy nhiên, bảo hộ lâu dài có thể duy trì doanh nghiệp kém hiệu quả và tăng chi phí hộ gia đình. Chính phủ nên xác định mục đích công rõ ràng, đặt ngày xem xét lại và tài trợ đào tạo lại hay đầu tư vùng thay vì che chắn mọi nhà sản xuất vô thời hạn.', focusVi:'Thân bài 2 trình bày lý do bảo hộ, giới hạn và biện pháp thay thế lâu dài.' },
      { en: 'Free trade can increase choice and productivity, but rapid adjustment may harm particular workers and regions. Governments should remain open to trade while helping affected communities gain new skills and protecting essential supply capacity. Carefully limited safeguards are more defensible than broad, permanent barriers.', vi: 'Thương mại tự do có thể tăng lựa chọn và năng suất, nhưng điều chỉnh nhanh có thể gây hại cho một số người lao động và vùng miền. Chính phủ nên duy trì thương mại mở đồng thời giúp cộng đồng bị ảnh hưởng học kỹ năng mới và bảo vệ năng lực cung ứng thiết yếu. Biện pháp bảo vệ giới hạn cẩn trọng có cơ sở hơn rào cản rộng và lâu dài.', focusVi:'Kết luận cân bằng hiệu quả thị trường và hỗ trợ nhóm chịu tác động.' },
    ],
    vocabulary: [
      { phrase: 'domestic market', meaningVi: 'thị trường trong nước', noteVi: 'Cụm đối lập với overseas market.' },
      { phrase: 'supply disruption', meaningVi: 'gián đoạn nguồn cung', noteVi: 'Cụm thường dùng trong chủ đề an ninh kinh tế.' },
      { phrase: 'permanent barriers', meaningVi: 'rào cản lâu dài', noteVi: 'Cụm chỉ chính sách bảo hộ kéo dài.' },
    ],
  },
];

export const WRITING_SAMPLES_EXTRA_DISCUSSION_2: WritingSample[] = SEEDS.map(makeDiscussion);
